style.css:
/*---已读链接---*/
a:visited, .fl:visited { color: #CC0000 !important} 

/*---网页选中链接字体---*/
a:hover {text-shadow: #690BC7 0px 1px 0px !important;}

/*---网页选中字体---*/
body ::-moz-selection {color:#000000;background-color:#E18B8D;text-shadow:none;}

/*---字体增强---*/
body, input {text-shadow: 0px 0px 1px #999;}

menubar > menu, menubar, menubutton, menulist, menuitem {
text-shadow: 0px 0px 1px #999;}

menupopup > * {
text-shadow: 0px 0px 1px #999;}

dialog, box, button, page, label, caption, textbox, input, select {
text-shadow: 0px 0px 1px #999;}

window {
text-shadow: 0px 0px 1px #999;}

/*---链接指向---*/
IMG:hover{box-shadow: 0 0 1px 1px green !important;}
A>IMG:hover{box-shadow: 0 0 1px 1px blue !important;}
A[target="_blank"]>img:hover{box-shadow: 0 0 1px 1px red !important;}
A:hover{color:blue !important;text-shadow:0 0 1px !important;}
A[target="_blank"]:hover{color:red !important;}

/*清除网页干扰码*/
body{ -moz-user-select:element !important;}
